<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FinOps Dashboard — PT Borneo Prima</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body>
<header class="topbar"><img src="/images/logo-bp.svg" alt="Borneo Prima"><div><strong>PT BORNEO PRIMA</strong><small>ACCOUNTING &amp; MINING COST DASHBOARD</small></div><label>Period <input id="period" type="month" value="2026-10"></label><select id="mode"><option value="mtd">MTD</option><option value="ytd">YTD</option></select></header>
<main class="dashboard"><section class="hero"><div><span class="eyebrow">FINOPS CONTROL CENTER</span><h1>Dashboard Overview</h1><p>Operational cost and production signals in one view.</p></div><button id="refresh">Refresh data</button></section><section class="cards"><article><span>ALL COST</span><strong id="allCost">—</strong><small>Report Cost</small></article><article><span>TOTAL COGP</span><strong id="cogp">—</strong><small>Cost of goods produced</small></article><article><span>TOTAL EXPENSE</span><strong id="expense">—</strong><small>Operating expense</small></article><article><span>DATA STATUS</span><strong class="status">LIVE</strong><small id="updated">Loading…</small></article></section><section class="panel"><div class="panel-head"><h2>Cost Matrix</h2><span id="source">—</span></div><div id="message" class="message">Loading dashboard data…</div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Account name</th><th>All Cost</th><th>COGP</th><th>Expense</th></tr></thead><tbody id="rows"></tbody></table></div></section></main><footer>FinOps-Dashboard · PT Borneo Prima</footer>
<script>const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(v||0));async function load(){const p=document.querySelector('#period').value,m=document.querySelector('#mode').value,msg=document.querySelector('#message');msg.textContent='Loading…';try{const r=await fetch(`/api/cost-matrix?period=${p}&mode=${m}`);if(!r.ok)throw new Error('API error');const {data}=await r.json();document.querySelector('#allCost').textContent=money(data.grandTotal.allCost);document.querySelector('#cogp').textContent=money(data.grandTotal.totalCOGP);document.querySelector('#expense').textContent=money(data.grandTotal.totalExpense);document.querySelector('#source').textContent=`${data.dataSource} · ${data.period}`;document.querySelector('#updated').textContent=`${data.rows.length} account rows`;document.querySelector('#rows').innerHTML=data.rows.filter(x=>!x.isParent).slice(0,30).map(x=>`<tr><td>${x.code}</td><td>${x.name}</td><td>${money(x.allCost)}</td><td>${money(x.totalCOGP)}</td><td>${money(x.totalExpense)}</td></tr>`).join('');msg.textContent=''}catch(e){msg.textContent=e.message}}document.querySelector('#refresh').onclick=load;document.querySelector('#period').onchange=load;document.querySelector('#mode').onchange=load;load();</script></body></html>
